import { PortfolioRepository, fileToBase64 } from "./cms-github.js";
import { buildProjectFiles, prepareCover, prepareImage, categoryLabel, folderName, slugify } from "./project.js";
import {
  CONTENT_PATHS, cleanLines, joinLines, parseProject, serializeProject, parseProfile, serializeProfile,
  parseArticle, serializeArticle, parsePhotographyEntry, serializePhotographyEntry, formatBytes, escapeHtml,
  parseSiteUpdated, serializeSiteUpdated, parseProductions, serializeProductions
} from "./contracts.js";

const STORAGE = { token: "pilgrimAdminToken", session: "pilgrimAdminSessionToken", repository: "pilgrimAdminRepository", branch: "pilgrimAdminBranch" };
const SECTIONS = [["overview", "Overview", "icon-eye"], ["content", "Content", "icon-folder"], ["about", "About", "icon-user"], ["publishing", "Publishing", "icon-rocket"], ["settings", "Settings", "icon-settings"]];
const state = { repo: null, section: "overview", contentType: "projects", data: {}, projects: [], articles: [], photography: [], commits: [], dragId: null, assetVersion: Date.now(), createTrigger: null };
const $ = id => document.getElementById(id);
const connectForm = $("connect-form");
const connectMessage = $("connect-message");
const startupScreen = $("startup-screen");
const connectScreen = $("connect-screen");

$("repository").value = localStorage.getItem(STORAGE.repository) || $("repository").value;
$("branch").value = localStorage.getItem(STORAGE.branch) || $("branch").value;
connectForm.addEventListener("submit", event => { event.preventDefault(); connect({ repository: $("repository").value.trim(), branch: $("branch").value.trim(), token: $("token").value.trim(), remember: $("remember-token").checked }); });

async function connect(credentials, silent = false) {
  const button = connectForm.querySelector("button[type='submit']"); button.disabled = true;
  if (silent) showStartup("Restoring your secure publishing session…");
  connectMessage.textContent = silent ? "Restoring secure session…" : "Checking repository access…";
  try {
    const repo = new PortfolioRepository(credentials); await repo.verify();
    await Promise.all([repo.getText(CONTENT_PATHS.projects), repo.getText("JS/projects.js")]).catch(() => { throw new Error("This repository does not match the Pilgrim portfolio structure."); });
    state.repo = repo; localStorage.setItem(STORAGE.repository, repo.repository); localStorage.setItem(STORAGE.branch, repo.branch); sessionStorage.setItem(STORAGE.session, credentials.token);
    if (credentials.remember) localStorage.setItem(STORAGE.token, credentials.token); else localStorage.removeItem(STORAGE.token);
    await loadAll(); mountCms();
  } catch (error) { if (silent) showConnect(friendlyError(error)); else connectMessage.textContent = friendlyError(error); }
  finally { button.disabled = false; }
}
function showStartup(message) { startupScreen.hidden = false; startupScreen.setAttribute("aria-busy", "true"); connectScreen.hidden = true; $("startup-status").textContent = message; }
function showConnect(message = "") { startupScreen.hidden = true; startupScreen.removeAttribute("aria-busy"); connectScreen.hidden = false; if (message) connectMessage.textContent = message; }

async function loadAll() {
  showBusy("Loading portfolio", "Reading the current content from GitHub…", 15);
  try { state.data = Object.fromEntries(await Promise.all(Object.entries(CONTENT_PATHS).map(async ([key, path]) => [key, await state.repo.getText(path, "")] ))); await Promise.all([loadProjects(), loadArticles(), loadPhotography(), loadCommits()]); }
  finally { hideBusy(); }
}
async function loadProjects() {
  const selected = new Set(cleanLines(state.data.selectedWork));
  state.projects = (await Promise.all(cleanLines(state.data.projects).map(async folder => { const base = `Projects/${folder}`; try { const [description, categories, card, stats, media] = await Promise.all([state.repo.getText(`${base}/description.txt`), state.repo.getText(`${base}/categories.txt`, "other\n"), state.repo.getText(`${base}/card.txt`, ""), state.repo.getText(`${base}/stats.txt`, ""), state.repo.getText(`${base}/media.txt`, "")]); return { ...parseProject({ folder, description, categories, card, stats, media }), selected: selected.has(folder) }; } catch { return null; } }))).filter(Boolean);
}
async function loadArticles() { state.articles = (await Promise.all(cleanLines(state.data.articles).map(async folder => { try { return parseArticle(folder, await state.repo.getText(`Articles/${folder}/article.txt`), await state.repo.getText(`Articles/${folder}/author-note.txt`, "")); } catch { return null; } }))).filter(Boolean); }
async function loadPhotography() { state.photography = (await Promise.all(cleanLines(state.data.photographyCollections).map(async folder => { const base = folder === "." ? "Projects/Photography" : `Projects/Photography/Collections/${folder}`; try { return parsePhotographyEntry(folder, await state.repo.getText(`${base}/entry.txt`), await state.repo.getText(`${base}/media.txt`, "")); } catch { return null; } }))).filter(Boolean); }
async function loadCommits({ suppressErrors = true } = {}) { try { state.commits = await state.repo.listCommits(30); } catch (error) { state.commits = []; if (!suppressErrors) throw error; } }

function mountCms() {
  startupScreen.hidden = true; connectScreen.hidden = true; const shell = $("app-shell"); shell.hidden = false; shell.className = "cms-shell";
  shell.innerHTML = `${sidebarHtml()}<main class="cms-main"><header class="cms-topbar"><div class="cms-mobile-title">${brandMark()}<strong id="mobile-section-title">Overview</strong></div><div class="cms-repo"><svg><use href="#icon-github"></use></svg><strong class="repo-name">${escapeHtml(state.repo.repository)}</strong><span>Branch</span><strong>${escapeHtml(state.repo.branch)}</strong><span class="sync">Synced</span></div><div class="cms-top-actions"><button class="button button-primary" id="create-content" type="button" aria-haspopup="dialog"><svg><use href="#icon-plus"></use></svg><span>Create</span></button><a class="button button-quiet" href="https://subtlesayak.github.io/" target="_blank" rel="noopener noreferrer">View site <svg><use href="#icon-external"></use></svg></a></div></header><section class="cms-content" id="cms-content"></section></main>${bottomNavHtml()}<div class="drawer-backdrop" id="drawer-backdrop"></div><aside class="editor-drawer" id="editor-drawer" aria-hidden="true"></aside>${createDialogHtml()}<div class="toast" id="cms-toast" role="status"></div><div class="busy-cover" id="cms-busy"><div class="busy-card"><h2 id="busy-title">Publishing</h2><p id="busy-detail"></p><div class="busy-progress"><span id="busy-progress"></span></div></div></div>`;
  bindNavigation(); $("drawer-backdrop").addEventListener("click", closeDrawer); $("create-content").addEventListener("click", event => openCreateDialog(event.currentTarget));
  $("create-dialog").addEventListener("close", () => state.createTrigger?.focus()); $("create-dialog").querySelectorAll("[data-create-type]").forEach(button => button.addEventListener("click", () => chooseCreate(button.dataset.createType)));
  renderSection(state.section);
}
function brandMark() { return `<img class="brand-mark" src="../Resources/favicon/pilfav.png?v=${state.assetVersion}" alt="">`; }
function createDialogHtml() { return `<dialog class="create-dialog" id="create-dialog" aria-labelledby="create-title"><form method="dialog"><header><div><p class="eyebrow">Portfolio content</p><h2 id="create-title">Create new</h2><p>Choose the kind of entry you want to publish.</p></div><button class="icon-button" type="submit" aria-label="Close">×</button></header><div class="create-options"><button type="button" data-create-type="projects"><svg><use href="#icon-folder"></use></svg><strong>Project</strong><span>A case study or portfolio entry.</span></button><button type="button" data-create-type="photography"><svg><use href="#icon-image"></use></svg><strong>Photo collection</strong><span>An event or multi-image gallery.</span></button><button type="button" data-create-type="articles"><svg><use href="#icon-edit"></use></svg><strong>Article</strong><span>A long-form writing entry.</span></button></div></form></dialog>`; }
function openCreateDialog(trigger) { state.createTrigger = trigger; const dialog = $("create-dialog"); if (!dialog.open) dialog.showModal(); }
function chooseCreate(type) { $("create-dialog").close(); state.contentType = type; renderSection("content"); ({ projects: () => openProjectEditor(null), photography: () => openPhotographyEditor(null), articles: () => openArticleEditor(null) }[type])(); }
function sidebarHtml() { return `<aside class="cms-sidebar"><div class="cms-brand">${brandMark()}<span>Pilgrim Studio</span></div><nav class="cms-nav">${SECTIONS.map(([id, label, icon]) => `<button type="button" data-section="${id}"><svg><use href="#${icon}"></use></svg><span>${label}</span></button>`).join("")}</nav><div class="cms-account"><span>Repository</span><strong>${escapeHtml(state.repo.repository)}</strong><span>${escapeHtml(state.repo.branch)}</span></div></aside>`; }
function bottomNavHtml() { return `<nav class="cms-bottom-nav">${SECTIONS.map(([id, label, icon]) => `<button type="button" data-section="${id}"><svg><use href="#${icon}"></use></svg><span>${label}</span></button>`).join("")}</nav>`; }
function bindNavigation() { document.querySelectorAll("[data-section]").forEach(button => button.addEventListener("click", () => renderSection(button.dataset.section))); }
function renderSection(section) { state.section = section; document.querySelectorAll("[data-section]").forEach(button => button.classList.toggle("is-active", button.dataset.section === section)); const label = SECTIONS.find(([id]) => id === section)?.[1] || "Portfolio"; $("mobile-section-title").textContent = label; closeDrawer(); ({ overview: renderOverview, content: renderContent, about: renderAboutPage, publishing: renderPublishing, settings: renderSettings }[section] || renderOverview)(); }
function heading(title, description, action = "") { return `<div class="cms-heading"><div><h1>${escapeHtml(title)}</h1><p>${escapeHtml(description)}</p></div>${action}</div>`; }

function renderOverview() { const content = $("cms-content"); content.innerHTML = `${heading("Overview", "Everything published from this repository, in one place.")}<div class="overview-grid"><div class="overview-stat"><strong>${state.projects.length}</strong><span>Portfolio projects</span></div><div class="overview-stat"><strong>${state.photography.length}</strong><span>Photo collections</span></div><div class="overview-stat"><strong>${state.articles.length}</strong><span>Articles</span></div><div class="overview-stat"><strong>${state.commits.length}</strong><span>Published versions</span></div></div><div class="overview-sections"><section class="cms-panel"><div class="panel-head"><h2>Publishing status</h2></div><div class="quick-list"><button data-go="publishing"><span>${escapeHtml(state.commits[0]?.commit?.message?.split("\n")[0] || "View publishing history")}</span><span>→</span></button></div></section><section class="cms-panel"><div class="panel-head"><h2>Portfolio workspace</h2></div><div class="quick-list"><button data-go="content"><span>Manage all portfolio content</span><span>→</span></button><button data-go="about"><span>Update profile, résumé, and homepage</span><span>→</span></button></div></section></div>`; content.querySelectorAll("[data-go]").forEach(button => button.addEventListener("click", () => renderSection(button.dataset.go))); }
function renderContent() { const content = $("cms-content"); content.innerHTML = `${heading("Content", "Manage your portfolio projects, photo collections, and articles.")}<section class="content-hub"><div class="panel-head"><h2>Manage content</h2><span>Create a new entry from the top + button.</span></div><div class="content-tabs" role="tablist">${[["projects", "Projects"], ["photography", "Photo collections"], ["articles", "Articles"]].map(([id, label]) => `<button class="content-tab ${state.contentType === id ? "is-active" : ""}" type="button" role="tab" aria-selected="${state.contentType === id}" data-content-type="${id}">${label}</button>`).join("")}</div><div class="content-surface" id="content-surface"></div></section>`; content.querySelectorAll("[data-content-type]").forEach(button => button.addEventListener("click", () => { state.contentType = button.dataset.contentType; renderContent(); })); drawContentSurface(); }
function drawContentSurface() { if (state.contentType === "projects") drawProjectsContent(); if (state.contentType === "photography") drawPhotographyContent(); if (state.contentType === "articles") drawArticlesContent(); }
function drawProjectsContent() { const surface = $("content-surface"); surface.innerHTML = `<div class="cms-toolbar"><input id="project-search" placeholder="Search projects…"><select id="project-filter"><option value="">All categories</option>${categoryOptions("")}</select></div><div class="content-list" id="project-list"></div>`; $("project-search").addEventListener("input", drawProjectRows); $("project-filter").addEventListener("change", drawProjectRows); drawProjectRows(); }
function drawProjectRows() { const list = $("project-list"); if (!list) return; const query = $("project-search").value.toLowerCase(), filter = $("project-filter").value; const items = state.projects.filter(project => (!query || `${project.title} ${project.cardContext}`.toLowerCase().includes(query)) && (!filter || project.category === filter)); list.innerHTML = items.length ? items.map(project => `<div class="content-row" draggable="true" data-id="${escapeHtml(project.id)}"><span class="row-handle">⠿</span><div class="row-primary"><img src="${rawUrl(project.cover)}" alt=""><strong>${escapeHtml(project.title)}</strong></div><span>${escapeHtml(categoryLabel(project.category))}</span><span>${escapeHtml(project.year || "—")}</span><div class="row-actions"><button class="icon-button ${project.selected ? "is-selected" : ""}" data-feature="${escapeHtml(project.id)}" title="Toggle selected work">★</button><button class="icon-button primary-action" data-edit="${escapeHtml(project.id)}" title="Edit"><svg><use href="#icon-edit"></use></svg></button></div></div>`).join("") : `<div class="empty-list">No matching projects.</div>`; list.querySelectorAll("[data-edit]").forEach(button => button.addEventListener("click", () => openProjectEditor(state.projects.find(item => item.id === button.dataset.edit)))); list.querySelectorAll("[data-feature]").forEach(button => button.addEventListener("click", () => toggleSelected(button.dataset.feature))); bindReorder(list, state.projects, CONTENT_PATHS.projects, "Reorder portfolio projects"); }

function openProjectEditor(project) { const isNew = !project, value = project || { title: "", description: "", tags: "", category: "uiux", year: String(new Date().getFullYear()), role: "Designer", cardLabel: "Case Study", cardContext: "", media: "", selected: false, cover: "", stats: "" }; openDrawer(`${isNew ? "New" : "Edit"} project`, isNew ? "Create a complete portfolio entry." : `Editing ${value.folder}`, `<form id="project-editor"><div class="drawer-body"><div class="cms-form-grid"><label class="cms-field wide">Title<input name="title" required value="${escapeHtml(value.title)}"></label><label class="cms-field">Category<select name="category">${categoryOptions(value.category)}</select></label><label class="cms-field">Year<input name="year" value="${escapeHtml(value.year)}"></label><label class="cms-field wide">Short description<textarea name="description" required>${escapeHtml(value.description)}</textarea></label><label class="cms-field wide">Tools and tags<input name="tags" value="${escapeHtml(value.tags)}"></label><label class="cms-field">Role<input name="role" value="${escapeHtml(value.role)}"></label><label class="cms-field">Card label<input name="cardLabel" value="${escapeHtml(value.cardLabel)}"></label><label class="cms-field wide">Card context<textarea name="cardContext">${escapeHtml(value.cardContext)}</textarea></label></div><div class="form-section"><span class="form-section-title">Cover image</span>${value.cover ? `<div class="remote-cover"><img src="${rawUrl(value.cover)}" alt="Current cover"><label class="asset-action"><strong>Replace cover</strong><input name="cover" type="file" accept="image/*"></label></div>` : `<label class="upload-box"><span><strong>Choose cover image</strong><small>Required for a new project</small></span><input name="cover" type="file" accept="image/*" hidden></label>`}</div><div class="form-section"><label class="cms-field wide">Gallery and external media<textarea name="media" rows="8" placeholder="One existing path or external URL per line">${escapeHtml(value.media)}</textarea></label><label class="upload-box"><span><strong>Add gallery images</strong><small>New images are appended as compressed WebP files</small></span><input name="gallery" type="file" accept="image/*" multiple hidden></label></div><label class="cms-check"><input name="selected" type="checkbox" ${value.selected ? "checked" : ""}><span>Feature in selected work</span></label></div><footer class="drawer-footer">${isNew ? "" : `<button type="button" class="danger-link" id="delete-project">Delete project</button>`}<button type="button" class="button button-quiet" data-close>Cancel</button><button type="submit" class="button button-primary">${isNew ? "Create & publish" : "Save & publish"}</button></footer></form>`); $("project-editor").addEventListener("submit", event => saveProject(event, project)); if (!isNew) $("delete-project").addEventListener("click", () => deleteProject(project)); }
async function saveProject(event, existing) { event.preventDefault(); const form = event.currentTarget, data = Object.fromEntries(new FormData(form)); try { let files = [], title = data.title.trim(); if (!existing) { if (await state.repo.pathExists(`Projects/${folderName(title)}`)) throw new Error("A project folder with this title already exists."); const coverFile = form.elements.cover.files[0]; if (!coverFile) throw new Error("Choose a cover image."); const cover = await prepareCover(coverFile), gallery = []; for (const file of Array.from(form.elements.gallery.files).slice(0, 12)) gallery.push(await prepareImage(file, gallery.length + 1)); const built = buildProjectFiles({ title, description: data.description, tags: data.tags, category: data.category, year: data.year, role: data.role, cardLabel: data.cardLabel, mediaUrls: data.media, selectedWork: Boolean(data.selected), cover, gallery }); files = built.files; files.push({ path: CONTENT_PATHS.projects, content: joinLines([...cleanLines(state.data.projects), built.folder]) }); if (data.selected) files.push({ path: CONTENT_PATHS.selectedWork, content: joinLines([...cleanLines(state.data.selectedWork), built.folder]) }); } else { const next = { ...existing, title, description: data.description, tags: data.tags, category: data.category, year: data.year, role: data.role, cardLabel: data.cardLabel, cardContext: data.cardContext || data.description, media: data.media, selected: Boolean(data.selected) }, base = `Projects/${existing.folder}`, galleryFiles = Array.from(form.elements.gallery.files).slice(0, 12), coverFile = form.elements.cover.files[0]; if (coverFile) { const cover = await prepareCover(coverFile); next.cover = `${base}/assets/cover.webp`; files.push({ path: `${base}/assets/cover.webp`, content: cover.base64, encoding: "base64" }); } const media = cleanLines(next.media); let imageIndex = media.filter(line => /^assets\/image-/.test(line)).length; for (const file of galleryFiles) { const image = await prepareImage(file, ++imageIndex); media.push(`assets/${image.name}`); files.push({ path: `${base}/assets/${image.name}`, content: image.base64, encoding: "base64" }); } next.media = media.join("\n"); next.stats = [next.role && `Role: ${next.role}`, next.year && `Timeline: ${next.year}`, `Category: ${categoryLabel(next.category)}`, next.tags && `Tools: ${next.tags}`].filter(Boolean).join("\n") + "\n"; const serialized = serializeProject(next); files.push({ path: `${base}/description.txt`, content: serialized.description }, { path: `${base}/categories.txt`, content: serialized.categories }, { path: `${base}/card.txt`, content: serialized.card }, { path: `${base}/stats.txt`, content: serialized.stats }, { path: `${base}/media.txt`, content: serialized.media }); files.push({ path: CONTENT_PATHS.selectedWork, content: updateMembership(state.data.selectedWork, existing.folder, Boolean(data.selected)) }); } await publish(files, `${existing ? "Update" : "Add"} portfolio project: ${title}`); closeDrawer(); await refresh("content"); } catch (error) { toast(friendlyError(error), true); } }
async function toggleSelected(id) { const project = state.projects.find(item => item.id === id); if (!project) return; try { await publish([{ path: CONTENT_PATHS.selectedWork, content: updateMembership(state.data.selectedWork, id, !project.selected) }], `${project.selected ? "Remove" : "Add"} selected work: ${project.title}`); await refresh("content"); } catch {} }
async function deleteProject(project) { if (!confirm(`Delete “${project.title}” and its uploaded files? Git history will still retain the previous version.`)) return; try { const paths = await state.repo.filesUnder(`Projects/${project.folder}`), projects = cleanLines(state.data.projects).filter(item => item !== project.folder), selected = cleanLines(state.data.selectedWork).filter(item => item !== project.folder); await publish([...paths.map(path => ({ path, delete: true })), { path: CONTENT_PATHS.projects, content: joinLines(projects) }, { path: CONTENT_PATHS.selectedWork, content: joinLines(selected) }], `Delete portfolio project: ${project.title}`); closeDrawer(); await refresh("content"); } catch {} }

function drawArticlesContent() { const surface = $("content-surface"); surface.innerHTML = `<div class="content-list" id="article-list">${state.articles.map(article => simpleRow(article.id, article.title, article.date, "Article")).join("") || `<div class="empty-list">No articles yet.</div>`}</div>`; bindSimpleEditors("article-list", state.articles, openArticleEditor); bindReorder($("article-list"), state.articles, CONTENT_PATHS.articles, "Reorder articles"); }
function openArticleEditor(article) { const value = article || { title: "", date: "", summary: "", body: "", authorNote: "" }; openDrawer(article ? "Edit article" : "New article", article ? `Editing ${article.folder}` : "Write and publish a new article.", `<form id="article-editor"><div class="drawer-body"><div class="cms-form-grid"><label class="cms-field wide">Title<input name="title" required value="${escapeHtml(value.title)}"></label><label class="cms-field wide">Date<input name="date" value="${escapeHtml(value.date)}" placeholder="July 2026"></label><label class="cms-field wide">Card summary<textarea name="summary" required>${escapeHtml(value.summary)}</textarea></label><label class="cms-field wide">Article body<textarea name="body" rows="18" required>${escapeHtml(value.body)}</textarea></label><label class="cms-field wide">Author note<textarea name="authorNote">${escapeHtml(value.authorNote)}</textarea></label></div></div><footer class="drawer-footer">${article ? `<button type="button" class="danger-link" id="delete-article">Delete article</button>` : ""}<button type="button" class="button button-quiet" data-close>Cancel</button><button class="button button-primary" type="submit">Save & publish</button></footer></form>`); $("article-editor").addEventListener("submit", event => saveArticle(event, article)); if (article) $("delete-article").addEventListener("click", () => deleteFolderItem(article, "Articles", CONTENT_PATHS.articles, "article")); }
async function saveArticle(event, existing) { event.preventDefault(); try { const data = Object.fromEntries(new FormData(event.currentTarget)), folder = existing?.folder || folderName(data.title), article = { ...data, folder }; if (!existing && await state.repo.pathExists(`Articles/${folder}`)) throw new Error("An article folder with this title already exists."); const files = [{ path: `Articles/${folder}/article.txt`, content: serializeArticle(article) }, { path: `Articles/${folder}/author-note.txt`, content: data.authorNote.trim() + "\n" }]; if (!existing) files.push({ path: CONTENT_PATHS.articles, content: joinLines([...cleanLines(state.data.articles), folder]) }); await publish(files, `${existing ? "Update" : "Add"} article: ${data.title}`); closeDrawer(); await refresh("content"); } catch (error) { toast(friendlyError(error), true); } }
function drawPhotographyContent() { const surface = $("content-surface"); surface.innerHTML = `<div class="content-list" id="photo-list">${state.photography.map(item => simpleRow(item.id, item.title, item.date, item.location || "Photography")).join("") || `<div class="empty-list">No collections yet.</div>`}</div>`; bindSimpleEditors("photo-list", state.photography, openPhotographyEditor); bindReorder($("photo-list"), state.photography, CONTENT_PATHS.photographyCollections, "Reorder photography collections"); }
function openPhotographyEditor(collection) { const value = collection || { title: "", date: "", location: "", description: "", captions: "", media: "" }; openDrawer(collection ? "Edit collection" : "New collection", collection?.folder === "." ? "Editing the root photography collection" : collection ? `Editing ${collection.folder}` : "Create a multi-image gallery.", `<form id="photo-editor"><div class="drawer-body"><div class="cms-form-grid"><label class="cms-field wide">Collection title<input name="title" required value="${escapeHtml(value.title)}"></label><label class="cms-field">Date<input name="date" value="${escapeHtml(value.date)}"></label><label class="cms-field">Location<input name="location" value="${escapeHtml(value.location)}"></label><label class="cms-field wide">Context<textarea name="description">${escapeHtml(value.description)}</textarea></label><label class="cms-field wide">Published media filenames<textarea name="media" rows="8">${escapeHtml(value.media)}</textarea></label><label class="cms-field wide">Captions<textarea name="captions" rows="7" placeholder="filename.webp: Caption text">${escapeHtml(value.captions)}</textarea></label></div><label class="upload-box"><span><strong>Add photographs</strong><small>Images are compressed to WebP and thumbnails are created</small></span><input name="photos" type="file" accept="image/*" multiple hidden></label></div><footer class="drawer-footer">${collection && collection.folder !== "." ? `<button type="button" class="danger-link" id="delete-photo">Delete collection</button>` : ""}<button type="button" class="button button-quiet" data-close>Cancel</button><button class="button button-primary" type="submit">Save & publish</button></footer></form>`); $("photo-editor").addEventListener("submit", event => savePhotography(event, collection)); if (collection && collection.folder !== ".") $("delete-photo").addEventListener("click", () => deleteFolderItem(collection, "Projects/Photography/Collections", CONTENT_PATHS.photographyCollections, "photography collection")); }
async function savePhotography(event, existing) { event.preventDefault(); try { const form = event.currentTarget, data = Object.fromEntries(new FormData(form)), folder = existing?.folder || folderName(data.title), base = folder === "." ? "Projects/Photography" : `Projects/Photography/Collections/${folder}`, media = cleanLines(data.media), files = []; if (!existing && await state.repo.pathExists(base)) throw new Error("A photography collection with this title already exists."); for (const file of Array.from(form.elements.photos.files)) { const image = await prepareImage(file, media.length + 1, { maxDimension: 2400, quality: .88 }); media.push(image.name); files.push({ path: `${base}/${image.name}`, content: image.base64, encoding: "base64" }, { path: `${base}/thumbs/${image.name}`, content: image.base64, encoding: "base64" }); } const collection = { ...data, folder, media: media.join("\n") }; files.push({ path: `${base}/entry.txt`, content: serializePhotographyEntry(collection) }, { path: `${base}/media.txt`, content: joinLines(media) }); if (!existing) files.push({ path: CONTENT_PATHS.photographyCollections, content: joinLines([...cleanLines(state.data.photographyCollections), folder]) }); await publish(files, `${existing ? "Update" : "Add"} photography collection: ${data.title}`); closeDrawer(); await refresh("content"); } catch (error) { toast(friendlyError(error), true); } }

