bindDirtyForm = (form, stateId, buttonId) => { const markDirty = () => { form.dataset.dirty = "true"; state.dirtyForm = form; $(stateId).textContent = "Unsaved changes"; $(buttonId).disabled = false; }; form.addEventListener("input", markDirty); form.addEventListener("change", markDirty); };
openDrawer = (title, subtitle, content) => { const drawer = $("editor-drawer"); state.drawerReturnFocus = document.activeElement instanceof HTMLElement ? document.activeElement : null; drawer.innerHTML = `<header class="drawer-head"><div><h2 id="drawer-title">${escapeHtml(title)}</h2><p>${escapeHtml(subtitle)}</p></div><button class="icon-button" data-close aria-label="Close editor">×</button></header>${content}`; drawer.classList.add("is-open"); drawer.setAttribute("aria-hidden", "false"); drawer.setAttribute("role", "dialog"); drawer.setAttribute("aria-modal", "true"); drawer.setAttribute("aria-labelledby", "drawer-title"); drawer.tabIndex = -1; $("drawer-backdrop").classList.add("is-open"); setShellInert(true); drawer.querySelectorAll("[data-close]").forEach(button => button.addEventListener("click", closeDrawer)); requestAnimationFrame(() => (drawer.querySelector("input, textarea, select, button") || drawer).focus()); };
closeDrawer = () => { const drawer = $("editor-drawer"); if (!drawer?.classList.contains("is-open")) return; drawer.classList.remove("is-open"); drawer.setAttribute("aria-hidden", "true"); $("drawer-backdrop")?.classList.remove("is-open"); setShellInert(false); const trigger = state.drawerReturnFocus; state.drawerReturnFocus = null; if (trigger?.isConnected) requestAnimationFrame(() => trigger.focus()); };
showBusy = (title, detail, progress = 8) => { const busy = $("cms-busy"); if (!busy) return; $("busy-title").textContent = title; $("busy-detail").textContent = detail; $("busy-detail").setAttribute("role", "status"); $("busy-progress").style.width = `${progress}%`; busy.setAttribute("role", "dialog"); busy.setAttribute("aria-modal", "true"); busy.setAttribute("aria-labelledby", "busy-title"); busy.setAttribute("aria-describedby", "busy-detail"); busy.classList.add("is-visible"); setShellInert(true); const card = busy.querySelector(".busy-card"); card.tabIndex = -1; requestAnimationFrame(() => card.focus()); };
hideBusy = () => { $("cms-busy")?.classList.remove("is-visible"); setShellInert(Boolean($("editor-drawer")?.classList.contains("is-open"))); };

function stagedSelectedWork() {
  if (!Array.isArray(state.selectedWorkDraft)) state.selectedWorkDraft = cleanLines(state.data.selectedWork);
  return state.selectedWorkDraft;
}
function selectedWorkHasChanges() {
  const current = cleanLines(state.data.selectedWork), draft = stagedSelectedWork();
  return current.length !== draft.length || current.some((id, index) => id !== draft[index]);
}
function stageSelectedProject(id) {
  const draft = stagedSelectedWork();
  state.selectedWorkDraft = draft.includes(id) ? draft.filter(item => item !== id) : [...draft, id];
  drawProjectRows();
}
async function publishSelectedProjects() {
  const draft = stagedSelectedWork();
  if (!selectedWorkHasChanges()) return;
  const names = state.projects.filter(project => draft.includes(project.id)).map(project => project.title);
  const summary = names.length ? names.slice(0, 8).map(title => `• ${title}`).join("\n") + (names.length > 8 ? `\n• and ${names.length - 8} more` : "") : "No projects will be featured.";
  if (!confirm(`Publish ${draft.length} selected ${draft.length === 1 ? "project" : "projects"} to the homepage?\n\n${summary}`)) return;
  try {
    await publish([{ path: CONTENT_PATHS.selectedWork, content: joinLines(draft) }], `Update selected work (${draft.length})`);
    state.selectedWorkDraft = null;
    await refresh("content");
  } catch (error) {
    toast(friendlyError(error), true);
  }
}
drawProjectsContent = () => {
  const surface = $("content-surface");
  surface.innerHTML = `<div class="cms-toolbar"><input id="project-search" placeholder="Search projects…"><select id="project-filter"><option value="">All categories</option>${categoryOptions("")}</select></div><div class="selected-work-actions" id="selected-work-actions"></div><div class="content-list" id="project-list"></div>`;
  $("project-search").addEventListener("input", drawProjectRows);
  $("project-filter").addEventListener("change", drawProjectRows);
  drawProjectRows();
};
drawProjectRows = () => {
  const list = $("project-list");
  if (!list) return;
  const draft = stagedSelectedWork(), query = $("project-search").value.toLowerCase(), filter = $("project-filter").value;
  const items = state.projects.filter(project => (!query || `${project.title} ${project.cardContext}`.toLowerCase().includes(query)) && (!filter || project.category === filter));
  list.innerHTML = items.length ? items.map(project => {
    const selected = draft.includes(project.id);
    return `<div class="content-row ${selected ? "is-selected" : ""}" draggable="true" data-id="${escapeHtml(project.id)}"><span class="row-handle">⠿</span><div class="row-primary"><img src="${rawUrl(project.cover)}" alt=""><strong>${escapeHtml(project.title)}</strong></div><span>${escapeHtml(categoryLabel(project.category))}</span><span>${escapeHtml(project.year || "—")}</span><div class="row-actions"><button class="icon-button ${selected ? "is-selected" : ""}" data-feature="${escapeHtml(project.id)}" type="button" aria-pressed="${selected}" aria-label="${selected ? "Remove" : "Add"} ${escapeHtml(project.title)} ${selected ? "from" : "to"} selected work" title="${selected ? "Remove from" : "Add to"} selected work">★</button><button class="icon-button primary-action" data-edit="${escapeHtml(project.id)}" type="button" title="Edit"><svg><use href="#icon-edit"></use></svg></button></div></div>`;
  }).join("") : `<div class="empty-list">No matching projects.</div>`;
  const actions = $("selected-work-actions"), selectedCount = draft.length, changed = selectedWorkHasChanges();
  actions.innerHTML = `<div class="selected-work-bar" role="status"><div class="selected-work-copy"><strong>${selectedCount} ${selectedCount === 1 ? "project" : "projects"} selected for the homepage</strong><span>${changed ? "Review the selection, then confirm to publish it immediately." : "Choose one or more projects with the star buttons."}</span></div><button class="button button-primary" id="publish-selected-work" type="button" ${changed ? "" : "disabled"}>Confirm &amp; publish</button></div>`;
  list.querySelectorAll("[data-edit]").forEach(button => button.addEventListener("click", () => openProjectEditor(state.projects.find(item => item.id === button.dataset.edit))));
  list.querySelectorAll("[data-feature]").forEach(button => button.addEventListener("click", () => stageSelectedProject(button.dataset.feature)));
  $("publish-selected-work").addEventListener("click", publishSelectedProjects);
  bindReorder(list, state.projects, CONTENT_PATHS.projects, "Reorder portfolio projects");
};
refresh = async (section = state.section) => {
  state.selectedWorkDraft = null;
  state.assetVersion = Date.now();
  await loadAll();
  renderSection(section);
};

const PRODUCTION_ICON_TYPES = new Set(["image/png", "image/jpeg", "image/webp", "image/avif"]);
const PRODUCTION_ICON_EXTENSIONS = { "image/png": "png", "image/jpeg": "jpg", "image/webp": "webp", "image/avif": "avif" };

function productionRecordKey(item) {
  return [item.title, item.company, item.time].map(value => String(value || "").trim()).join("\u0001");
}

function productionIconId(item) {
  let hash = 2166136261;
  for (const character of productionRecordKey(item)) {
    hash ^= character.charCodeAt(0);
    hash = Math.imul(hash, 16777619);
  }
  return (hash >>> 0).toString(36);
}

function productionIconPath(item, file) {
  const institution = slugify(item.company || item.title || "institution");
  return `Resources/work-experience/${institution}/logo-${productionIconId(item)}.${PRODUCTION_ICON_EXTENSIONS[file.type]}`;
}

function validateProductionIconFile(file) {
  if (!PRODUCTION_ICON_TYPES.has(file.type)) throw new Error("Choose a PNG, JPG, WebP, or AVIF image.");
  if (file.size > 4 * 1024 * 1024) throw new Error("Icon images must be 4 MB or smaller.");
}

function normalizeProductionIconSource(value) {
  const source = String(value || "").trim();
  if (/^https:\/\/[^\s]+$/i.test(source)) return source;
  const localPath = source.replace(/^\/+/, "");
  if (/^Resources\/[a-zA-Z0-9._/-]+$/.test(localPath) && !localPath.split("/").includes("..")) return localPath;
  throw new Error("Use an HTTPS image URL, a Resources/ path, or upload an image.");
}

function serializedProductionText(value) {
  const text = String(value || "").trim();
  return text ? `${text}\n` : "";
}

function renderProductionIconCards(items) {
  if (!items.length) return `<p class="production-icon-empty">Add an experience or education record below, then save it to create its icon control.</p>`;
  return items.map((item, index) => {
    const identity = item.company || item.title || `Record ${index + 1}`;
    const inputId = `production-icon-source-${index}`;
    return `<article class="production-icon-card"><div class="production-icon-preview-wrap"><img class="production-icon-preview" data-production-icon-preview="${index}" src="${escapeHtml(assetUrl(item.thumbnail))}" alt="${escapeHtml(`${identity} icon`)}"></div><div class="production-icon-copy"><p class="production-icon-eyebrow">${escapeHtml(item.company || "Institution or company")}</p><h3>${escapeHtml(item.title || "Untitled record")}</h3><p class="production-icon-meta">${escapeHtml(item.time || "No date or location")}</p><div class="cms-field production-icon-source"><label for="${inputId}">Icon image URL or site path</label><div class="production-icon-source-row"><input id="${inputId}" data-production-icon-source="${index}" type="text" inputmode="url" autocomplete="url" value="${escapeHtml(item.thumbnail)}" placeholder="https://… or Resources/…"><button class="icon-button production-icon-refresh" data-production-icon-refresh="${index}" type="button" aria-label="Refresh ${escapeHtml(identity)} icon preview" title="Refresh icon preview"><svg aria-hidden="true"><use href="#icon-refresh"></use></svg></button></div></div><div class="production-icon-actions"><label class="button button-quiet production-icon-upload">Choose image<input data-production-icon-file="${index}" type="file" accept="image/png,image/jpeg,image/webp,image/avif" hidden></label><span class="production-icon-status" data-production-icon-status="${index}" role="status" aria-live="polite">${item.thumbnail ? "Current image" : "No image selected"}</span></div></div></article>`;
  }).join("");
}

function releaseProductionIconPreviews() {
  (state.productionIconPreviewUrls || []).forEach(url => URL.revokeObjectURL(url));
  state.productionIconPreviewUrls = [];
}

function bindProductionIconControls(form) {
  form.querySelectorAll("[data-production-icon-file]").forEach(input => input.addEventListener("change", event => {
    const file = event.currentTarget.files?.[0];
    if (!file) return;
    try { validateProductionIconFile(file); }
    catch (error) { event.stopPropagation(); event.currentTarget.value = ""; toast(error.message, true); return; }
    const index = event.currentTarget.dataset.productionIconFile;
    const preview = form.querySelector(`[data-production-icon-preview="${index}"]`);
    if (preview) {
      if (preview.dataset.objectUrl) URL.revokeObjectURL(preview.dataset.objectUrl);
      const objectUrl = URL.createObjectURL(file);
      preview.src = objectUrl;
      preview.dataset.objectUrl = objectUrl;
      state.productionIconPreviewUrls = [...(state.productionIconPreviewUrls || []), objectUrl];
    }
    const status = form.querySelector(`[data-production-icon-status="${index}"]`);
    if (status) status.textContent = `${file.name} will publish with About`;
  }));
  form.querySelectorAll("[data-production-icon-source]").forEach(input => input.addEventListener("input", event => {
    const index = event.currentTarget.dataset.productionIconSource;
    const fileInput = form.querySelector(`[data-production-icon-file="${index}"]`);
    if (fileInput?.files?.length) fileInput.value = "";
    const status = form.querySelector(`[data-production-icon-status="${index}"]`);
    if (status) status.textContent = event.currentTarget.value.trim() ? "Source changed. Refresh preview, then publish." : "Choose an image before publishing";
  }));
  form.querySelectorAll("[data-production-icon-refresh]").forEach(button => button.addEventListener("click", () => {
    const index = button.dataset.productionIconRefresh;
    const input = form.querySelector(`[data-production-icon-source="${index}"]`);
    const preview = form.querySelector(`[data-production-icon-preview="${index}"]`);
    const status = form.querySelector(`[data-production-icon-status="${index}"]`);
    const fileInput = form.querySelector(`[data-production-icon-file="${index}"]`);
    if (!input || !preview) return;

    let source;
    try { source = normalizeProductionIconSource(input.value); }
    catch (error) { if (status) status.textContent = error.message; toast(error.message, true); input.focus(); return; }

    if (fileInput?.files?.length) fileInput.value = "";
    if (preview.dataset.objectUrl) {
      URL.revokeObjectURL(preview.dataset.objectUrl);
      delete preview.dataset.objectUrl;
    }
    state.assetVersion = Date.now();
    button.disabled = true;
    button.setAttribute("aria-busy", "true");
    if (status) status.textContent = "Refreshing preview…";
    preview.onload = () => {
      button.disabled = false;
      button.removeAttribute("aria-busy");
      if (status) status.textContent = "Preview refreshed from this source.";
    };
    preview.onerror = () => {
      button.disabled = false;
      button.removeAttribute("aria-busy");
      if (status) status.textContent = "Could not load this image source.";
    };
    preview.src = assetUrl(source);
  }));
}

async function collectProductionIconChanges(form, rawText) {
  const currentItems = parseProductions(state.data.productions);
  const nextItems = parseProductions(rawText);
  const nextByKey = new Map(nextItems.map(item => [productionRecordKey(item), item]));
  const files = [];
  let changed = false;

  for (const input of form.querySelectorAll("[data-production-icon-source]")) {
    const index = Number(input.dataset.productionIconSource);
    const current = currentItems[index];
    if (!current) continue;
    const file = form.querySelector(`[data-production-icon-file="${index}"]`)?.files?.[0];
    const source = input.value.trim();
    if (!file && source === current.thumbnail.trim()) continue;
    const target = nextByKey.get(productionRecordKey(current));
    if (!target) throw new Error(`Save the text changes for “${current.company || current.title}” before changing its icon.`);

    if (file) {
      validateProductionIconFile(file);
      target.thumbnail = productionIconPath(target, file);
      files.push({ path: target.thumbnail, content: await fileToBase64(file), encoding: "base64" });
    } else {
      target.thumbnail = normalizeProductionIconSource(source);
    }
    changed = true;
  }

  return { files, content: changed ? serializeProductions(nextItems) : serializedProductionText(rawText) };
}

